% Import data from text file %[task:8b32]
training_data = readtable("/home/matlab/srcs/begbaj/phm-america-2025/Data/PHM2025_training_data/training_data.csv");

% Display results
training_data %[task:8b32] %[output:3d1c0aa3]

%%
% Check for rows containing NaN / missing values
nan_rows = any(ismissing(training_data), 2);

% Count how many rows contain at least one missing value
nRowsWithNaN = sum(nan_rows);   % or nRowsWithNaN = nnz(nan_rows);

% Display result and optionally list indices
fprintf('Number of rows with NaN/missing values: %d\n', nRowsWithNaN);
rowsIndices = find(nan_rows);   % indices of rows that contain missing values
%%
% 1. Calculate the correlation matrix
% Assuming 'train' is a table or a matrix in MATLAB
cm = corr(table2array(training_data)); 

% 2. Create the Heatmap
figure('Position', [100, 100, 800, 800]); % Set figure size %[output:10a8dbaf]
h = heatmap(cm, 'Colormap', sky, 'ColorLimits', [-1 1]); %[output:10a8dbaf]

% 3. Add Labels and Formatting
h.Title = 'Correlation Matrix Heatmap'; %[output:10a8dbaf]
h.XDisplayLabels = train.Properties.VariableNames; %[output:3ae35eb0]
h.YDisplayLabels = train.Properties.VariableNames;

% Note: To show values (annot=True), MATLAB heatmaps do this by default.
% To format them to 2 decimal places:
h.ColorData = round(cm, 2);
%%
% Example table (replace with your data)
T = training_data %[output:1923e7c9]

% 1) Drop any rows containing NaN
Tclean = rmmissing(T);  % removes rows with any missing values

% 2) Extract numeric matrix (preserves variable order)
X = table2array(Tclean);

% 3) Compute correlation matrix (Pearson by default)
R = corr(X, 'Rows', 'complete');  % 'complete' is safe here after rmmissing

% 4) Make a labeled matrix (table) with same variable names
Rtable = array2table(R, 'VariableNames', Tclean.Properties.VariableNames, ...
                         'RowNames', Tclean.Properties.VariableNames);

% Display
Rtable %[output:9840543a]
%%
% Assume T is your original table
Tclean = rmmissing(T);                       % drop rows with any NaN
X = table2array(Tclean);                     % numeric data
R = corr(X, 'Rows', 'complete');            % correlation matrix
names = Tclean.Properties.VariableNames;     % labels

% Create heatmap
h = heatmap(names, names, R, 'Colormap', parula, 'ColorLimits', [-1 1]); %[output:7a43510b]

% Improve appearance
h.Title = 'Correlation Matrix'; %[output:7a43510b]
h.XLabel = 'Variables'; %[output:7a43510b]
h.YLabel = 'Variables'; %[output:7a43510b]
h.CellLabelFormat = '%.2f';                  % show values in cells %[output:7a43510b]
%%
% Example data (replace with your snapshots)
T = training_data %[output:2039e27d]
Y = randn(T,S);        % snapshots: rows=time, columns=sensors %[output:31e29ae1]

maxW = 8;
windows = cell(S, maxW);
stats.mean = cell(S, maxW);
stats.std  = cell(S, maxW);

for s = 1:S
    xs = Y(:,s);                       % time series for sensor s
    % Optionally remove rows with NaN in this sensor (drop snapshots)
    validIdx = ~isnan(xs);
    xs = xs(validIdx);
    Tvalid = numel(xs);
    for w = 1:maxW
        Nw = Tvalid - w + 1;
        if Nw <= 0
            windows{s,w} = [];         % not enough samples for this window length
            stats.mean{s,w} = [];
            stats.std{s,w}  = [];
            continue
        end
        % Preallocate: each column is one window of length w
        W = zeros(w, Nw);
        for k = 1:Nw
            W(:,k) = xs(k:(k+w-1));
        end
        windows{s,w} = W;
        % compute simple stats along each window (column-wise)
        stats.mean{s,w} = mean(W, 1);
        stats.std{s,w}  = std(W, 0, 1);
    end
end
%%
% Vectorized window creation for one sensor and window length w
% assumes xs is column vector, Tvalid >= w
% result W is w x (Tvalid-w+1)
W = hankel(xs(1:w), xs(w:end));

